import{_ as t,a,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 15 Secrecy in industry","description":"学习 whether 引导名词性从句，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 15 Secrecy in industry","description":"学习 whether 引导名词性从句，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 whether 引导名词性从句，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 14 The Butterfly Effect","link":"/life/english/new-concept/book-4/unit-02/lesson-014"},"next":{"text":"第四册：流利英语 · Lesson 16 The modern city","link":"/life/english/new-concept/book-4/unit-02/lesson-016"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 14 The Butterfly Effect","link":"/life/english/new-concept/book-4/unit-02/lesson-014"},"next":{"text":"第四册：流利英语 · Lesson 16 The modern city","link":"/life/english/new-concept/book-4/unit-02/lesson-016"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-02/lesson-015.md","filePath":"life/english/new-concept/book-4/unit-02/lesson-015.md"}'),r={name:"life/english/new-concept/book-4/unit-02/lesson-015.md"};function o(l,e,s,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第四册-流利英语-·-lesson-15-secrecy-in-industry" tabindex="-1">第四册：流利英语 · Lesson 15 Secrecy in industry <a class="header-anchor" href="#第四册-流利英语-·-lesson-15-secrecy-in-industry" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 15 Secrecy in industry&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕工业研发中的保密与知识交流，练习讨论相互冲突的利益：企业希望保护成果，研究者也需要交流和检验。不要把保密一概视为好或坏，而要说明资料类型、共享对象和风险条件。重点使用名词性从句表达未知问题与决策依据。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>secrecy</td><td>/ˈsiːkrəsi/</td><td>n.</td><td>保密</td><td>industrial secrecy</td></tr><tr><td>patent</td><td>/ˈpætənt/</td><td>n.</td><td>专利</td><td>apply for a patent</td></tr><tr><td>disclosure</td><td>/dɪsˈkləʊʒə/</td><td>n.</td><td>披露</td><td>public disclosure</td></tr><tr><td>collaboration</td><td>/kəˌlæbəˈreɪʃən/</td><td>n.</td><td>合作</td><td>research collaboration</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>keep confidential — 保密</li><li>weigh up — 权衡因素</li></ul><h2 id="语法讲解-whether-引导名词性从句" tabindex="-1">语法讲解：whether 引导名词性从句 <a class="header-anchor" href="#语法讲解-whether-引导名词性从句" aria-label="Permalink to &quot;语法讲解：whether 引导名词性从句&quot;">​</a></h2><p>whether 可引导“是否”意义的主语、宾语或表语从句，后面采用陈述语序。We must decide whether the data can be shared. 不能写 whether can the data be shared。放在介词之后或接 to do 时一般用 whether，不用 if，例如 debate about whether…、whether to publish。whether…or… 可列出选择；它提出一个待解决问题，不表示作者已经选定其中一项。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The team must decide whether the preliminary data can be shared with partners.</p></blockquote><p>团队必须决定是否可以与合作伙伴共享初步数据。</p><p>whether 从句作 decide 的宾语；the preliminary data 在 can 前，保持陈述语序。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>whether can the data be shared 是错误疑问语序；嵌入从句用 whether the data can be shared。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>把 whether the data can be shared 连成一个意群；避免在 whether 后用升调，误读成独立问句。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>We need to decide whether to share the test data. Collaboration could help another team check our results. Before release, we should identify any confidential information.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句团队讨论记录：待决策事项、共享的一个好处、需要核查的一个条件。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>whether to 提出选择，could 说明可能收益，before 限定发布前的检查。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：They discussed ___ to publish the design.（whether / if）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> whether</p><p><strong>解析：</strong> whether 可以直接接不定式，if 通常不能。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>改错：We asked whether was the file confidential.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> We asked whether the file was confidential.</p><p><strong>解析：</strong> 宾语从句使用陈述语序。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>示例是否已经批准共享？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> must decide 表决策尚待完成。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：whether 引导名词性从句。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-014">上一课</a> · <a href="/life/english/new-concept/book-4/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-02/lesson-016">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(r,[["render",o]]);export{u as __pageData,b as default};
